INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱全忠败秦宗权围蔡州", "start_year": 888, "end_year": 888, "time_original": "888年五月至六月前；具体日未载", "dynasty": "唐", "description": "朱全忠大举攻秦宗权，于蔡州南击败其军、攻取北关门；秦宗权守中州，朱全忠分兵列二十八寨包围。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8a944d3a-ca2c-5b83-b490-7f663b9736f6"}, {"title": "李茂贞加检校侍中", "start_year": 888, "end_year": 888, "time_original": "888年五月至六月前；具体日未载", "dynasty": "唐", "description": "朝廷加凤翔节度使李茂贞检校侍中。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d2f34a73-e62d-5d8d-90f3-dcdafb9b41bc"}, {"title": "王建陈敬瑄相攻，王建议借朝命", "start_year": 888, "end_year": 888, "time_original": "888年五月至六月前；具体日未载", "dynasty": "唐", "description": "陈敬瑄与王建交战，西川贡赋中断。王建一度想罢兵，周庠、綦毋谏反对；王建决定请朝廷派大臣主持西川事务。", "phases": [], "location_name": "成都、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "87322f06-488d-5965-b2c8-71284d73c61a"}, {"title": "王建与顾彦朗分别上表朝廷", "start_year": 888, "end_year": 888, "time_original": "888年五月至六月前；具体日未载", "dynasty": "唐", "description": "王建使周庠起草奏表，请求讨陈敬瑄并求邛州；顾彦朗也上表请求赦免王建、调陈敬瑄他镇。", "phases": [], "location_name": "西川、东川、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "133ba376-afb9-56e6-85a0-44800901a813"}, {"title": "寿王李杰昔随僖宗入蜀时受田令孜鞭责", "start_year": null, "end_year": null, "time_original": "黄巢之乱时；具体年日未载", "dynasty": "唐", "description": "《通鉴》追叙寿王李杰昔随唐僖宗入蜀，行路困顿时向田令孜求马未得，反受其鞭责。", "phases": [], "location_name": "赴蜀山道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "737ec126-05a2-52c7-9038-daaca6b23ea7"}, {"title": "昭宗遣人监西川军遭田令孜拒绝", "start_year": 888, "end_year": 888, "time_original": "昭宗即位后至888年六月前", "dynasty": "唐", "description": "昭宗即位后遣人监督西川军，田令孜不奉诏。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d453600c-7874-51c2-a609-de87c7549a1a"}, {"title": "朝廷命韦昭度镇西川并征陈敬瑄", "start_year": 888, "end_year": 888, "time_original": "888年六月", "dynasty": "唐", "description": "朝廷命韦昭度兼中书令、充西川节度使和招抚制置等使，征陈敬瑄为龙武统军。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ce9d1fd2-003e-5c18-96be-7fa4c332e8a2"}, {"title": "王建令王宗瑶招地方武装", "start_year": 888, "end_year": 888, "time_original": "888年六月前后；具体日未载", "dynasty": "唐", "description": "王建屯新都时，绵竹何义阳、安仁费师懃等地方武装自保；王建遣王宗瑶劝说，各部归附并提供粮资，王建军势恢复。", "phases": [], "location_name": "新都、绵竹、安仁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e68cd005-d3f5-5d97-a4d4-0cab46d6f432"}, {"title": "朝廷置佑国军，任张全义节度使", "start_year": 888, "end_year": 888, "time_original": "888年六月前后；具体日未载", "dynasty": "唐", "description": "朝廷在河南府设置佑国军，以张全义为节度使。", "phases": [], "location_name": "河南府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a46fa5a4-f97e-5b06-a03e-a8a0a586b651"}, {"title": "李罕之引河东兵攻河阳被丁会击退", "start_year": 888, "end_year": 888, "time_original": "888年七月", "dynasty": "唐", "description": "李罕之率河东军攻河阳，丁会击退其军。", "phases": [], "location_name": "河阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ef62265f-8fc2-5f40-85da-a7ae197ca0b1"}, {"title": "凤州升节度府，满存受任", "start_year": 888, "end_year": 888, "time_original": "888年七月；具体日未载", "dynasty": "唐", "description": "朝廷将凤州升为节度府，划兴、利二州隶属，任凤州防御使满存为节度使、同平章事。", "phases": [], "location_name": "凤州、兴州、利州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "badf2c65-1b7b-5321-b2f3-c990eadd054a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

